-- outbox (all four states: pending, scheduled, dead-lettered, processed)

-- Scheduled is the one bucket a fixed timestamp cannot express: it means "backed off past
-- *now*", so a message written with a 2026 availableAt reads as Pending the moment the clock
-- passes it, and the demo would show an empty column forever. These few rows are rebased onto
-- the moment the database is built instead. Every other state is a statement about the past and
-- stays true however long the sample sits there.
UPDATE "outbox" SET Data = json_set(Data, '$.availableAt', strftime('%Y-%m-%dT%H:%M:%S', 'now', '+15 minutes') || '+00:00') WHERE Id = '019fb80716207037b6889f2d9890012f';
UPDATE "outbox" SET Data = json_set(Data, '$.availableAt', strftime('%Y-%m-%dT%H:%M:%S', 'now', '+4 minutes') || '+00:00') WHERE Id = '019fb80abfa0703887ca9b1113dc6393';
UPDATE "outbox" SET Data = json_set(Data, '$.availableAt', strftime('%Y-%m-%dT%H:%M:%S', 'now', '+3 minutes') || '+00:00') WHERE Id = '019fb809d540703993c24c57a5ef8596';

